/bin/zsh -lc "python3.12 -B -c 'from solution import load_people
h = \"name,email,age,active\\n\"
checks = 0
def valid(text, expected):
    global checks
    assert load_people(text) == expected
    checks += 1
def invalid(text):
    global checks
    try: load_people(text)
    except ValueError: checks += 1
    else: raise AssertionError(repr(text))
valid('\\''\\ufeff active , age , email , name \\r\\nFALSE,00130, A@B ,\"Doe, Jo\\nJr\"\\r\\n'\\'', [dict(name=\"Doe, Jo\\nJr\", email=\"a@b\", age=130, active=False)])
valid(h+\"\\n , , , , \\nSam,s@x,,\\n\", [dict(name=\"Sam\", email=\"s@x\", age=None, active=False)])
valid(h+'\\''\"Sam \"\"S\"\"\",s@x,0,TrUe\\n'\\'', [dict(name='\\''Sam \"S\"'\\'',email=\"s@x\",age=0,active=True)])
valid(h+\"Sam,s@x,\"+\"0\"*5000+\"130,0\\n\", [dict(name=\"Sam\",email=\"s@x\",age=130,active=False)])
for text in [\"\", \"\\n\", \"name,email,age,age\\n\", \"name,email,age,active,extra\\n\", \"\\ufeff\\ufeff\"+h]: invalid(text)
for row in ['\\''Sam,s@x,0'\\'', '\\''Sam,s@x,0,true,x'\\'', '\\'',s@x,0,true'\\'', '\\''Sam,,0,true'\\'', '\\''Sam,a@@b,0,true'\\'', '\\''Sam,@b,0,true'\\'', '\\''Sam,a@,0,true'\\'', '\\''Sam,a @b,0,true'\\'', '\\''Sam,s@x,-1,true'\\'', '\\''Sam,s@x,+1,true'\\'', '\\''Sam,s@x,1.0,true'\\'', '\\''Sam,s@x,١,true'\\'', '\\''Sam,s@x,131,true'\\'', '\\''Sam,s@x,1,yes'\\'', '\\''Sa\"m,s@x,1,true'\\'', '\\''\"Sam\"x,s@x,1,true'\\'', '\\''\"Sam,s@x,1,true'\\'']: invalid(h+row+\"\\n\")
print(f\"{checks} additional requirement checks passed\")
for label, row in [(\"long name\", \"S\"*140000+\",s@x,1,true\"), (\"long zero age\", \"Sam,s@x,\"+\"0\"*140000+\",true\")]:
    try:
        load_people(h+row+\"\\n\")
        print(label+\": accepted\")
    except ValueError as exc:
        print(label+\": REJECTED valid input: \"+str(exc)+\"; cause=\"+str(exc.__cause__))
